  ["sets"]={[127]={["bonuses"]={[1]={["description"]="(2 предмета) Сила оружия и заклинаний +|cffffff124|r",["index"]=1,["perfected"]=false,["required"]=2},[2]={["description"]="(3 предмета) Шанс крит. удара +|cffffff634|r",["index"]=2,["perfected"]=false,["required"]=3},[3]={["description"]="(4 предмета) Сила оружия и заклинаний +|cffffff124|r",["index"]=3,["perfected"]=false,["required"]=4},[4]={["description"]="(5 предметов) Ваши атаки с периодическим уроном, а также атаки с необходимостью поддержания наносят на |cffffff15%|r больше урона.",["index"]=4,["perfected"]=false,["required"]=5}},["familyId"]=127,["id"]=127,["max"]=5,["name"]="Смертоносный удар",["normal"]=5,["perfected"]=0},[683]={["bonuses"]={[1]={["description"]="(1 предмет) Восст. запаса сил +|cffffff67|r",["index"]=1,["perfected"]=false,["required"]=1},[2]={["description"]="(1 предмет) Восст. магии +|cffffff67|r",["index"]=2,["perfected"]=false,["required"]=1},[3]={["description"]="(1 предмет) Восст. здоровья +|cffffff67|r",["index"]=3,["perfected"]=false,["required"]=1},[4]={["description"]="(2 предмета) Находясь в бою, вы раз в секунду получаете заряд эффекта «Светотьма» (всего можно накопить не более 30 зарядов), который увеличивает ваше восстановление запаса сил, здоровья и магии на |cffffff8|r. Покидая бой, вы раз в секунду теряете один заряд эффекта.",["index"]=4,["perfected"]=false,["required"]=2}},["familyId"]=683,["id"]=683,["max"]=2,["name"]="Рокса Искалеченный",["normal"]=1,["perfected"]=0},[694]={["bonuses"]={[1]={["description"]="(1 предмет) Пробивание +|cffffff1650|r",["index"]=1,["perfected"]=false,["required"]=1},[2]={["description"]="(1 предмет) Урон, наносимый монстрам, увеличивается на |cffffff15%|r. Вы получаете постоянный эффект «Малая сила», увеличивающий ваш критический урон на |cffffff10%|r, а общий урон от ваших обычных и силовых атак уменьшается на |cffffff99%|r.",["index"]=2,["perfected"]=false,["required"]=1}},["familyId"]=694,["id"]=694,["max"]=1,["name"]="Амулет велотийского ур-мага",["normal"]=1,["perfected"]=0},[809]={["bonuses"]={[1]={["description"]="(2 предмета) Сила оружия и заклинаний +|cffffff124|r",["index"]=1,["perfected"]=false,["required"]=2},[2]={["description"]="(3 предмета) Шанс крит. удара +|cffffff634|r",["index"]=2,["perfected"]=false,["required"]=3},[3]={["description"]="(4 предмета) Пробивание +|cffffff1435|r",["index"]=3,["perfected"]=false,["required"]=4},[4]={["description"]="(5 предметов) Прямой урон, наносимый монстрам, увеличивается на |cffffff15%|r.",["index"]=4,["perfected"]=false,["required"]=5}},["familyId"]=809,["id"]=809,["max"]=5,["name"]="Ловчий рожденных-приливом",["normal"]=5,["perfected"]=0}},
  ["skills"]={
    {["description"]="Создавая или расходуя знаки, вы меняете ход судьбы, отчего ваши критические урон и исцеление увеличиваются на |cffffff12%|r на |cffffff7|r сек.",["id"]=184847,["lineActive"]=true,["name"]="Роковая фортуна",["passive"]=true,["purchased"]=true,["rank"]=2,["skillType"]=1},
    {["description"]="Вы меняете форму и структуру своей души одним усилием воли.\13\n\13\nКогда вы восстанавливаете магию или запас сил, ваша сила оружия и заклинаний увеличивается на |cffffff284|r на |cffffff10|r сек.",["id"]=184858,["lineActive"]=true,["name"]="Покоренная квинтэссенция",["passive"]=true,["purchased"]=true,["rank"]=2,["skillType"]=1},
    {["description"]="Ваши атаки калечат разум противников еретическими знаниями, увеличивая урон, наносимый эффектами состояния, на |cffffff15%|r и шанс наложения эффектов состояния — на |cffffff55%|r.",["id"]=184873,["lineActive"]=true,["name"]="Сила мысли",["passive"]=true,["purchased"]=true,["rank"]=2,["skillType"]=1},
    {["description"]="Неизвестность убивает. Ваше физическое и магическое пробивание увеличивается на |cffffff1 240|r за каждую выбранную способность из ветки «Книжный вестник».\13\n\13\nТекущий бонус: |cffffff4 960|r.",["id"]=184887,["lineActive"]=true,["name"]="Раскрытые тайны",["passive"]=true,["purchased"]=true,["rank"]=2,["skillType"]=1},
    {["description"]="Вы призываете в свой разум таинственного воина, защищающего вас от враждебных чар. Пока на вас действует способность из ветки «Солдат Апокрифа» с положительными эффектами, ваш показатель брони увеличивается на |cffffff3 271|r.",["id"]=184923,["lineActive"]=true,["name"]="Эгида незримого",["passive"]=true,["purchased"]=true,["rank"]=2,["skillType"]=1},
    {["description"]="Знания из Апокрифа бурлят в глубинах вашего разума, увеличивая ваше восстановление здоровья, магии и запаса сил на |cffffff81|r за каждую выбранную способность из ветки «Солдат Апокрифа».\13\n\13\nТекущий бонус: |cffffff0|r.",["id"]=185036,["lineActive"]=true,["name"]="Источник Бездны",["passive"]=true,["purchased"]=true,["rank"]=2,["skillType"]=1},
    {["description"]="Использование любой способности мастера рун меняет течение судьбы и на |cffffff20|r сек. накладывает на вас и членов вашей группы эффект «Малое уклонение», который уменьшает урон от атак по площади на |cffffff10%|r. Этот эффект может срабатывать не чаще чем раз в |cffffff5|r сек.",["id"]=184932,["lineActive"]=true,["name"]="Обманутая судьба",["passive"]=true,["purchased"]=true,["rank"]=2,["skillType"]=1},
    {["description"]="Воля мастера рун нерушима. При поглощении знаков вы получаете |cffffff4|r очк. суперспособности. Этот эффект может срабатывать не чаще чем раз в |cffffff8|r сек.",["id"]=185058,["lineActive"]=true,["name"]="Неумолимый исход",["passive"]=true,["purchased"]=true,["rank"]=2,["skillType"]=1},
    {["description"]="Мастерство, с которым вы повелеваете судьбами и водами бездонного моря, увеличивает эффективность вашего исходящего лечения на |cffffff4%|r за каждый активный знак.",["id"]=185186,["lineActive"]=true,["name"]="Исцеляющие волны",["passive"]=true,["purchased"]=true,["rank"]=2,["skillType"]=1},
    {["description"]="Вы смотрели в бездну слишком долго. Создавая знаки, вы восстанавливаете |cffffff225|r ед. магии и запаса сил.",["id"]=185243,["lineActive"]=true,["name"]="Устрашающая ясность",["passive"]=true,["purchased"]=true,["rank"]=2,["skillType"]=1},
    {["description"]="Знание — сила. Ваша необычайная ученость увеличивает восстановление магии и запаса сил на |cffffff18%|r.",["id"]=185239,["lineActive"]=true,["name"]="Эрудиция",["passive"]=true,["purchased"]=true,["rank"]=2,["skillType"]=1},
    {["description"]="Ваш статус иллюмината уменьшает стоимость щитов, поглощающих урон, и увеличивает их эффективность на |cffffff10%|r.",["id"]=185195,["lineActive"]=true,["name"]="Затейливые руны",["passive"]=true,["purchased"]=true,["rank"]=2,["skillType"]=1},
    {["description"]="Станьте рукой, направляющей нити судьбы.\13\n\13\n«Неумолимый исход» 2-го ранга теперь создает максимальное количество знаков, но не чаще чем раз в |cffffff15|r сек. После срабатывания этого эффекта ваша сила оружия и заклинаний увеличивается на |cffffff300|r на |cffffff25|r сек.",["id"]=263398,["lineActive"]=true,["name"]="Исправленная судьба",["passive"]=true,["purchased"]=true,["rank"]=0,["skillType"]=1},
    {["description"]="Постигните древнее знание и начертайте новые руны раздора.\13\n\13\nТеперь способность «Доспех судьбы» на |cffffff4|r сек. накладывает на вашего противника эффект «Малая трусость», а на вас и членов вашей группы — эффект «Великая живучесть». Вы восстанавливаете |cffffff1|r очк. суперспособности за каждый активный знак.\13\n\13\nЭти эффекты могут срабатывать не чаще чем раз в |cffffff2|r сек.",["id"]=263412,["lineActive"]=true,["name"]="Усердие эрудита",["passive"]=true,["purchased"]=true,["rank"]=0,["skillType"]=1},
    {["description"]="Затраты запаса сил на использование способностей из ветки «Одноручное оружие и щит» уменьшаются на |cffffff7%|r, а затраты запаса сил на блокирование — на |cffffff18%|r.",["id"]=29420,["lineActive"]=true,["name"]="Твердыня",["passive"]=true,["purchased"]=true,["rank"]=1,["skillType"]=2},
    {["description"]="Ваша сила оружия и заклинаний увеличивается на |cffffff3|r%, а количество урона, которое вы можете заблокировать, — на |cffffff10%|r.",["id"]=29397,["lineActive"]=true,["name"]="Щит и меч",["passive"]=true,["purchased"]=true,["rank"]=1,["skillType"]=2},
    {["description"]="Ваши обычные прерывающие удары наносят на |cffffff250|r ед. больше урона, а также расходуют на |cffffff25%|r меньше запаса сил.",["id"]=29415,["lineActive"]=true,["name"]="Смертельный удар щитом",["passive"]=true,["purchased"]=true,["rank"]=1,["skillType"]=2},
    {["description"]="Повышает шанс наложения эффектов состояния на |cffffff100%|r.",["id"]=45512,["lineActive"]=true,["name"]="Сила стихий",["passive"]=true,["purchased"]=true,["rank"]=2,["skillType"]=2},
    {["description"]="Огненный посох увеличивает урон, наносимый вашими способностями с периодическим уроном и эффектами состояния, на |cffffff12%|r.\13\n\13\nГрозовой посох увеличивает урон, наносимый вашими способностями с прямым уроном и необходимостью поддержания, на |cffffff12%|r.\13\n\13\nМорозный посох уменьшает стоимость блокирования на |cffffff36%|r и увеличивает количество урона, которое вы можете заблокировать, на |cffffff20%|r.",["id"]=45513,["lineActive"]=true,["name"]="Древние знания",["passive"]=true,["purchased"]=true,["rank"]=2,["skillType"]=2},
    {["description"]="Каждая надетая часть легких доспехов накладывает следующие эффекты:\13\n\13\n— урон, получаемый от магических атак, уменьшается на |cffffff1%|r\13\n\13\n;— затраты на кувырок уменьшаются на |cffffff3%|r\13\n\13\n;— снижение скорости передвижения в режиме скрытности уменьшается на |cffffff5%|r\13\n\13\n;— затраты на освобождение уменьшаются на |cffffff5%|r\13\n\13\n;— затраты на прерывающие удары уменьшаются на |cffffff3%|r.",["id"]=150185,["lineActive"]=true,["name"]="Бонусы легких доспехов",["passive"]=true,["purchased"]=true,["rank"]=0,["skillType"]=3},
    {["description"]="Каждая надетая часть легких доспехов накладывает следующие эффекты:\13\n\13\n— урон, получаемый от боевых атак, увеличивается на |cffffff1%|r\13\n\13\n;— затраты на блокирование увеличиваются на |cffffff3%|r\13\n\13\n;— прерывающие удары наносят на |cffffff1%|r меньше урона.",["id"]=152778,["lineActive"]=true,["name"]="Штрафы легких доспехов",["passive"]=true,["purchased"]=true,["rank"]=0,["skillType"]=3},
    {["description"]="Каждая надетая часть средних доспехов накладывает следующие эффекты:\13\n\13\n— затраты на спринт уменьшаются на |cffffff1%|r\13\n\13\n;— затраты на передвижение в режиме скрытности уменьшаются на |cffffff5%|r\13\n\13\n;— затраты на блокирование уменьшаются на |cffffff3%|r\13\n\13\n;— после кувырка урон, получаемый вами от способностей, действующих по площади, уменьшается на |cffffff2%|r на |cffffff2|r сек.;\13\n\13\n— при невосприимчивости к эффектам контроля скорость передвижения повышается на |cffffff2%|r.",["id"]=150181,["lineActive"]=true,["name"]="Бонусы средних доспехов",["passive"]=true,["purchased"]=true,["rank"]=0,["skillType"]=3},
    {["description"]="Ваши критический урон и исходящее лечение увеличиваются на |cffffff2%|r за каждую надетую часть средних доспехов.\13\n\13\nТекущий бонус: |cffffff14%|r.",["id"]=45564,["lineActive"]=true,["name"]="Проворство",["passive"]=true,["purchased"]=true,["rank"]=3,["skillType"]=3},
    {["description"]="Восстановление запаса сил увеличивается на |cffffff4%|r за каждую надетую часть средних доспехов.\13\n\13\nТекущий бонус: |cffffff28%|r.\13\n\13\nЗатраты запаса сил на использование способностей уменьшаются на |cffffff2%|r за каждую надетую часть средних доспехов.\13\n\13\nТекущий бонус: |cffffff14%|r.",["id"]=45565,["lineActive"]=true,["name"]="Крылья ветра",["passive"]=true,["purchased"]=true,["rank"]=2,["skillType"]=3},
    {["description"]="Стоимость скрытности уменьшается на |cffffff7%|r за каждую надетую часть средних доспехов. \13\n\13\nТекущий бонус: |cffffff49%|r.\13\n\13\nРадиус обнаружения в скрытности уменьшается на |cffffff5%|r за каждую надетую часть средних доспехов. \13\n\13\nТекущий бонус: |cffffff35%|r.",["id"]=45567,["lineActive"]=true,["name"]="Улучшенная скрытность",["passive"]=true,["purchased"]=true,["rank"]=2,["skillType"]=3},
    {["description"]="Ваша сила оружия и заклинаний увеличивается на |cffffff2%|r за каждую надетую часть средних доспехов.\13\n\13\nТекущий бонус: |cffffff14%|r.",["id"]=45572,["lineActive"]=true,["name"]="Ловкость",["passive"]=true,["purchased"]=true,["rank"]=2,["skillType"]=3},
    {["description"]="Бонус к скорости во время спринта увеличивается на |cffffff3%|r за каждую надетую часть средних доспехов.\13\n\13\nТекущий бонус: |cffffff21%|r.\13\n\13\nСтоимость кувырка уменьшается на |cffffff4|r% за каждую надетую часть средних доспехов.\13\n\13\nТекущий бонус: |cffffff28%|r.",["id"]=45574,["lineActive"]=true,["name"]="Атлетика",["passive"]=true,["purchased"]=true,["rank"]=2,["skillType"]=3},
    {["description"]="Каждая надетая часть тяжелых доспехов накладывает следующие эффекты:\13\n\13\n— урон, получаемый от боевых атак, уменьшается на |cffffff1%|r\13\n\13\n;— блокирование отражает на |cffffff1%|r\13\n\13\n больше урона;— прерывающие удары наносят на |cffffff30|r\13\n\13\n ед. больше урона;— урон, получаемый при невосприимчивости к эффектам контроля, уменьшается на |cffffff1%|r.",["id"]=150184,["lineActive"]=true,["name"]="Бонусы тяжелых доспехов",["passive"]=true,["purchased"]=true,["rank"]=0,["skillType"]=3},
    {["description"]="Каждая надетая часть тяжелых доспехов накладывает следующие эффекты:\13\n\13\n— урон, получаемый от магических атак, увеличивается на |cffffff1%|r\13\n\13\n;— бонус к скорости от спринта уменьшается на |cffffff1%|r\13\n\13\n;— затраты на кувырок увеличиваются на |cffffff3%|r\13\n\13\n;— радиус обнаружения в режиме скрытности увеличивается на |cffffff10%|r.",["id"]=152780,["lineActive"]=true,["name"]="Штрафы тяжелых доспехов",["passive"]=true,["purchased"]=true,["rank"]=0,["skillType"]=3},
    {["description"]="Физическая и магическая сопротивляемость увеличивается на |cffffff229|r за каждую надетую часть тяжелых доспехов.\13\n\13\nТекущий бонус: |cffffff0|r.",["id"]=45531,["lineActive"]=true,["name"]="Решимость",["passive"]=true,["purchased"]=true,["rank"]=2,["skillType"]=3},
    {["description"]="Восстановление здоровья увеличивается на |cffffff4%|r за каждую надетую часть тяжелых доспехов.\13\n\13\nТекущий бонус: |cffffff0%|r.\13\n\13\nВы восстанавливаете |cffffff108|r ед. магии и запаса сил за каждую надетую часть тяжелых доспехов каждый раз, когда вам наносят урон. Этот эффект может срабатывать не чаще чем раз в |cffffff4|r сек.\13\n\13\nТекущий бонус: |cffffff0|r.",["id"]=45526,["lineActive"]=true,["name"]="Телосложение",["passive"]=true,["purchased"]=true,["rank"]=2,["skillType"]=3},
    {["description"]="Максимальный запас здоровья увеличивается на |cffffff1%|r за каждую надетую часть тяжелых доспехов. \13\n\13\nТекущий бонус: |cffffff0%|r.",["id"]=29804,["lineActive"]=true,["name"]="Джаггернаут",["passive"]=true,["purchased"]=true,["rank"]=1,["skillType"]=3},
    {["description"]="Голод терзает вас изнутри. Превратите его в грозное оружие, подобно Сторибегу.\13\n\13\nВы получаете возможность пожирать трупы (не более |cffffff4|r сек. на один труп). За каждую секунду пожирания трупов вы восстанавливаете |cffffff3 604|r ед. здоровья (в зависимости от вашего максимального запаса здоровья) и |cffffff15|r очк. суперспособности.\13\n\13\nЕсли вы вервольф-берсерк, каждый такт этой способности создает заряды эффекта «Ярость».",["id"]=32634,["lineActive"]=true,["name"]="Ненасытный голод",["passive"]=true,["purchased"]=true,["rank"]=0,["skillType"]=4},
    {["description"]="Вы можете применять убеждение в разговоре с персонажами.",["id"]=29061,["lineActive"]=true,["name"]="Дар убеждения",["passive"]=true,["purchased"]=true,["rank"]=0,["skillType"]=5},
    {["description"]="Вы можете применять угрозу в разговоре с персонажами.\13\n\13\nЗатраты запаса сил на использование способностей из ветки «Гильдия бойцов» уменьшаются на |cffffff15%|r.",["id"]=29062,["lineActive"]=true,["name"]="Грозный вид",["passive"]=true,["purchased"]=true,["rank"]=0,["skillType"]=5},
    {["description"]="Повсюду в Тамриэле спрятаны воровские тайники. Открыть их могут только члены Гильдии воров.",["id"]=74580,["lineActive"]=true,["name"]="Что нашел, то мое",["passive"]=true,["purchased"]=true,["rank"]=0,["skillType"]=5},
    {["description"]="Радиус обнаружения свидетелями и стражниками уменьшается на |cffffff10%|r. Свидетели и стражники будут реже замечать ваши преступные действия, однако эта способность не влияет на расстояние, с которого стражники будут пытаться вас задержать.",["id"]=76453,["lineActive"]=true,["name"]="Завеса теней",["passive"]=true,["purchased"]=true,["rank"]=0,["skillType"]=5},
    {["description"]="Вы призываете оружие Темного Братства и наносите смертельный удар ничего не подозревающей цели. За убийство этой цели вы получите на 75% меньше опыта.\13\n\13\nЭта способность не действует на игроков или сложные цели.",["id"]=78219,["lineActive"]=true,["name"]="Клинок Горя",["passive"]=true,["purchased"]=true,["rank"]=0,["skillType"]=5},
    {["description"]="После захвата лесопилки, фермы, шахты или крепости ваша сила оружия и заклинаний увеличивается на |cffffff5%|r, а восстановление здоровья, магии и запаса сил — на |cffffff10%|r на |cffffff10|r мин.\13\n\13\nВы получаете постоянный эффект «Спешка», повышающий скорость вашего верхового животного на |cffffff15%|r.",["id"]=39248,["lineActive"]=true,["name"]="Затяжная атака",["passive"]=true,["purchased"]=true,["rank"]=1,["skillType"]=6},
    {["description"]="Скорость получения опыта навыка «Посох восстановления» повышается на |cffffff15%|r.\13\n\13\nСкорость плавания повышается на |cffffff50%|r.",["id"]=36582,["lineActive"]=true,["name"]="Земноводность",["passive"]=true,["purchased"]=true,["rank"]=0,["skillType"]=7},
    {["description"]="Эффективность исходящего лечения повышается на |cffffff6%|r.",["id"]=45258,["lineActive"]=true,["name"]="Животворец",["passive"]=true,["purchased"]=true,["rank"]=3,["skillType"]=7},
    {["description"]="Ваш максимальный запас здоровья увеличивается на |cffffff1 000|r ед., а сопротивляемость ядам и болезням — на |cffffff2 310|r.",["id"]=45255,["lineActive"]=true,["name"]="Аргонианская стойкость",["passive"]=true,["purchased"]=true,["rank"]=3,["skillType"]=7},
    {["description"]="Ваш максимальный запас сил и магии увеличивается на |cffffff1 000|r ед.\13\n\13\nВыпив зелье, вы восстанавливаете себе |cffffff3 125|r ед. здоровья, магии и запаса сил.",["id"]=45247,["lineActive"]=true,["name"]="Находчивость",["passive"]=true,["purchased"]=true,["rank"]=3,["skillType"]=7},
    {["description"]="Позволяет использовать рецепты до 19-го уровня включительно.",["id"]=44590,["lineActive"]=true,["name"]="Улучшение рецепта",["passive"]=true,["purchased"]=true,["rank"]=1,["skillType"]=8},
    {["description"]="Позволяет использовать стандартные (зеленые) рецепты.",["id"]=44625,["lineActive"]=true,["name"]="Качество рецепта",["passive"]=true,["purchased"]=true,["rank"]=1,["skillType"]=8},
    {["description"]="Позволяет алхимику использовать природную воду и жир для приготовления зелий и ядов 3-го уровня, а также чистую воду и ихор для приготовления зелий и ядов 10-го уровня.",["id"]=45542,["lineActive"]=true,["name"]="Знание растворителей",["passive"]=true,["purchased"]=true,["rank"]=1,["skillType"]=8},
    {["description"]="Позволяет использовать рунные камни силы Джора, Пораде, Джоде и Нотаде для создания глифов 1–15-го уровня.",["id"]=46727,["lineActive"]=true,["name"]="Улучшение силы",["passive"]=true,["purchased"]=true,["rank"]=1,["skillType"]=8},
    {["description"]="Позволяет использовать простые (белые) и стандартные (зеленые) рунные камни аспекта.",["id"]=46758,["lineActive"]=true,["name"]="Улучшение аспекта",["passive"]=true,["purchased"]=true,["rank"]=1,["skillType"]=8},
